    private function relation(string$type):array{$public=$type==='organization'?str_repeat('a',32):str_repeat('b',32);$state=$this->pdo->prepare('SELECT projection_sha256 FROM api_v2_directory_resource_state WHERE resource_type=?');$state->execute([$type]);return['externalId'=>$type==='organization'?'org-ext':'client-ext','expectedPublicId'=>$public,'expectedRevision'=>'1','expectedProjectionSha256'=>$state->fetchColumn()];}
    private function standaloneRelation():array{$state=$this->pdo->prepare('SELECT projection_sha256 FROM api_v2_directory_resource_state WHERE resource_type=? AND public_id=?');$state->execute(['client',str_repeat('d',32)]);return['externalId'=>'standalone-client-ext','expectedPublicId'=>str_repeat('d',32),'expectedRevision'=>'1','expectedProjectionSha256'=>$state->fetchColumn()];}
    private function createCommand(string $commandId,string $externalId='project-conflict'):array{return['commandId'=>$commandId,'externalId'=>$externalId,'expectedAuthorizationGeneration'=>'0','project'=>['name'=>'Shared name','description'=>'Safe scope','estimatedStart'=>'2026-09-01','estimatedEnd'=>'2026-09-30'],'organization'=>$this->relation('organization'),'client'=>$this->relation('client')];}
    private function assertSyncConflict(array $outcome,string $code,string $requestId,bool $verifiedIdentity=true):void
    {
        self::assertSame(409,$outcome['status']);self::assertSame($verifiedIdentity?['apiVersion','sourceInstanceId','applicationId','historyEpoch','requestId','error']:['apiVersion','requestId','error'],array_keys($outcome['payload']));self::assertSame(['code'=>$code],$outcome['payload']['error']);self::assertSame($requestId,$outcome['payload']['requestId']);
        $encoded=json_encode($outcome['payload'],JSON_THROW_ON_ERROR);foreach(['project-conflict','Shared name','Safe scope','org-ext','client-ext']as$privateValue)self::assertStringNotContainsString($privateValue,$encoded);self::assertArrayNotHasKey('result',$outcome['payload']);
    }
    private function portalState():array{return['workspace'=>$this->pdo->query('SELECT * FROM portal_v2_workspaces ORDER BY id')->fetchAll(PDO::FETCH_ASSOC),'projection'=>$this->pdo->query('SELECT * FROM portal_projection_state ORDER BY integration_profile_id,workspace_public_id')->fetchAll(PDO::FETCH_ASSOC),'outbox'=>$this->pdo->query('SELECT * FROM portal_projection_outbox ORDER BY id')->fetchAll(PDO::FETCH_ASSOC)];}
    private function assertPortalUnchanged(array$before):void{self::assertSame($before,$this->portalState(),'Project synchronization must be portal/delivery neutral.');}
    private function syncState():array{return['projects'=>$this->pdo->query('SELECT id,public_id,organization_id,client_id FROM projects ORDER BY id')->fetchAll(PDO::FETCH_ASSOC),'bindings'=>$this->pdo->query('SELECT * FROM api_v2_project_external_bindings ORDER BY external_id')->fetchAll(PDO::FETCH_ASSOC),'receipts'=>$this->pdo->query('SELECT * FROM api_v2_project_command_receipts ORDER BY command_id')->fetchAll(PDO::FETCH_ASSOC),'generation'=>$this->pdo->query('SELECT authorization_generation FROM api_v2_project_authorization_state WHERE application_pk=3')->fetchColumn()];}
    public function testCreateAcceptsOrganizationOnlyAndStandaloneClientOwnership():void
    {
        $portal=$this->portalState();$organizationOnly=$this->createCommand('713e4567-e89b-42d3-a456-426614174000','organization-only');$organizationOnly['client']=null;
        $first=api_v2_project_sync_write($this->pdo,'create',$organizationOnly,7,$this->headers,'organization-only');self::assertSame(201,$first['status']);self::assertSame('1',$first['payload']['result']['authorizationGeneration']);
        $standalone=$this->createCommand('723e4567-e89b-42d3-a456-426614174000','standalone-project');$standalone['expectedAuthorizationGeneration']='1';$standalone['organization']=null;$standalone['client']=$this->standaloneRelation();
        $second=api_v2_project_sync_write($this->pdo,'create',$standalone,7,$this->headers,'standalone');self::assertSame(201,$second['status']);self::assertSame('2',$second['payload']['result']['authorizationGeneration']);self::assertFalse($second['payload']['replayed']);
        self::assertTrue(api_v2_project_sync_write($this->pdo,'create',$standalone,7,$this->headers,'standalone-replay')['payload']['replayed']);
        $createdResource=$second['payload']['result']['resource'];$update=['commandId'=>'773e4567-e89b-42d3-a456-426614174000','externalId'=>'standalone-project','expectedRevision'=>$createdResource['revision'],'expectedProjectionSha256'=>$createdResource['projectionSha256'],'expectedAuthorizationGeneration'=>'2','project'=>['name'=>'Standalone updated','description'=>'Exact client retained','estimatedStart'=>'2026-10-01','estimatedEnd'=>'2026-10-31']];
        $updated=api_v2_project_sync_write($this->pdo,'update',$update,7,$this->headers,'standalone-update');self::assertSame(200,$updated['status']);self::assertSame('2',$updated['payload']['result']['resource']['revision']);self::assertSame(['portalPublished'=>false,'publicLinkEnabled'=>false],$updated['payload']['result']['presentation']);self::assertFalse($updated['payload']['replayed']);
        $updateReplay=api_v2_project_sync_write($this->pdo,'update',$update,7,$this->headers,'standalone-update-replay');self::assertSame(200,$updateReplay['status']);self::assertTrue($updateReplay['payload']['replayed']);self::assertSame($updated['payload']['result'],$updateReplay['payload']['result']);
        $stored=$this->pdo->query("SELECT organization_id,client_id FROM projects WHERE id=2")->fetch(PDO::FETCH_ASSOC);self::assertSame(['organization_id'=>null,'client_id'=>12],['organization_id'=>$stored['organization_id'],'client_id'=>(int)$stored['client_id']]);
        $read=api_v2_project_read($this->pdo,$createdResource['publicId'],7,$this->headers,'standalone-read');self::assertSame('Standalone updated',$read['data']['name']);self::assertSame(null,$read['data']['organizationPublicId']);self::assertSame(str_repeat('d',32),$read['data']['clientPublicId']);
        $inventory=api_v2_project_inventory_read($this->pdo,null,10,7,$this->headers,'standalone-inventory');self::assertSame(200,$inventory['status']);self::assertContains('standalone-project',array_column($inventory['payload']['projects'],'externalId'));self::assertStringNotContainsString(str_repeat('d',32),json_encode($inventory['payload'],JSON_THROW_ON_ERROR));
        $status=api_v2_project_binding_status_read($this->pdo,'standalone-project',7,$this->headers,'standalone-status');self::assertSame(200,$status['status']);self::assertSame($createdResource['publicId'],$status['payload']['binding']['publicId']);self::assertSame('2',$status['payload']['resource']['revision']);self::assertArrayNotHasKey('presentation',$status['payload']);$this->assertPortalUnchanged($portal);
    }
    public function testCreateRejectsInvalidOwnershipWithoutMutation():void
    {
        $cases=[];$bothNull=$this->createCommand('733e4567-e89b-42d3-a456-426614174000','both-null');$bothNull['organization']=null;$bothNull['client']=null;$cases[]=['parse',$bothNull];
        $boundWithoutOrg=$this->createCommand('743e4567-e89b-42d3-a456-426614174000','bound-without-org');$boundWithoutOrg['organization']=null;$cases[]=['relationship',$boundWithoutOrg];
        $standaloneWithOrg=$this->createCommand('753e4567-e89b-42d3-a456-426614174000','standalone-with-org');$standaloneWithOrg['client']=$this->standaloneRelation();$cases[]=['relationship',$standaloneWithOrg];
        $stale=$this->createCommand('763e4567-e89b-42d3-a456-426614174000','stale-standalone');$stale['organization']=null;$stale['client']=$this->standaloneRelation();$stale['client']['expectedRevision']='2';$cases[]=['relationship',$stale];
        foreach($cases as[$kind,$command]){$before=$this->syncState();if($kind==='parse'){self::assertNull(api_v2_project_sync_command_parse('create',json_encode($command,JSON_THROW_ON_ERROR)));}else{$this->assertSyncConflict(api_v2_project_sync_write($this->pdo,'create',$command,7,$this->headers,$command['externalId']),'relationship_proof_conflict',$command['externalId']);}self::assertSame($before,$this->syncState(),$command['externalId']);}
    }
