        $inventory=api_v2_project_inventory_read($this->pdo,null,10,7,$this->headers,'r7');self::assertSame(200,$inventory['status']);self::assertSame(['apiVersion','sourceInstanceId','applicationId','historyEpoch','requestId','authorizationGeneration','projects','nextCursor'],array_keys($inventory['payload']));self::assertCount(2,$inventory['payload']['projects']);self::assertSame(['externalId','publicId','revision','projectionSha256','status','archived'],array_keys($inventory['payload']['projects'][0]));self::assertArrayNotHasKey('budget',$inventory['payload']['projects'][0]);$id=(int)$this->pdo->query("SELECT id FROM projects WHERE public_id='".$resource['publicId']."'")->fetchColumn();$this->pdo->beginTransaction();$this->pdo->exec("UPDATE projects SET name='Browser edit' WHERE id=$id");$live=(new ProjectRevisionService($this->pdo))->advance($id,'update');$this->pdo->commit();
