    public function testSyncConflictsUseStableNonDisclosingReasons():void
    {
        $create=$this->createCommand('423e4567-e89b-42d3-a456-426614174000');$wrongIdentity=$this->headers;$wrongIdentity['application']='423e4567-e89b-42d3-a456-426614174000';$this->assertSyncConflict(api_v2_project_sync_write($this->pdo,'create',$create,7,$wrongIdentity,'identity'),'identity_conflict','identity',false);
        $staleGeneration=$this->createCommand('433e4567-e89b-42d3-a456-426614174000');$staleGeneration['expectedAuthorizationGeneration']='1';$this->assertSyncConflict(api_v2_project_sync_write($this->pdo,'create',$staleGeneration,7,$this->headers,'generation'),'authorization_generation_conflict','generation');
        $badProof=$this->createCommand('443e4567-e89b-42d3-a456-426614174000');$badProof['organization']['expectedRevision']='2';$this->assertSyncConflict(api_v2_project_sync_write($this->pdo,'create',$badProof,7,$this->headers,'relationship'),'relationship_proof_conflict','relationship');
        self::assertSame(201,api_v2_project_sync_write($this->pdo,'create',$create,7,$this->headers,'created')['status']);$changed=$create;$changed['project']['name']='Changed name';$this->assertSyncConflict(api_v2_project_sync_write($this->pdo,'create',$changed,7,$this->headers,'command-id'),'command_id_conflict','command-id');
        $duplicateBinding=$this->createCommand('463e4567-e89b-42d3-a456-426614174000');$duplicateBinding['expectedAuthorizationGeneration']='1';$this->assertSyncConflict(api_v2_project_sync_write($this->pdo,'create',$duplicateBinding,7,$this->headers,'binding'),'external_binding_conflict','binding');
        $this->pdo->exec("CREATE TRIGGER reject_project_sync_receipt BEFORE INSERT ON api_v2_project_command_receipts BEGIN SELECT RAISE(ABORT, 'private constraint detail'); END");$databaseConstraint=$this->createCommand('473e4567-e89b-42d3-a456-426614174000','other-project-conflict');$databaseConstraint['expectedAuthorizationGeneration']='1';$this->assertSyncConflict(api_v2_project_sync_write($this->pdo,'create',$databaseConstraint,7,$this->headers,'database'),'database_constraint_conflict','database');self::assertSame(1,(int)$this->pdo->query('SELECT COUNT(*) FROM projects')->fetchColumn());
