    public function testAdoptionCandidatesAreBoundedCanonicalAndCallingApplicationScoped():void
    {
        $insert=function(string$publicId,string$name,?string$archivedAt=null):array{$statement=$this->pdo->prepare("INSERT INTO projects(public_id,organization_id,client_id,name,status,archived_at,portal_publish_enabled,public_project_enabled,revision,source_version,invoice_billing_period,project_invoice_auto_email) VALUES(?,10,11,?,'not_started',?,1,1,1,'browser-v1','per_invoice',0)");$statement->execute([$publicId,$name,$archivedAt]);$id=(int)$this->pdo->lastInsertId();$this->pdo->beginTransaction();$project=(new ProjectRevisionService($this->pdo))->initialize($id,'baseline');$this->pdo->commit();return$project;};
