        $this->pdo->prepare('INSERT INTO api_v2_project_external_bindings VALUES(3,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)')->execute(['caller-bound',$boundHere['public_id'],(int)$boundHere['revision'],ProjectRevisionService::projectionHash($boundHere)]);
        $this->pdo->exec("INSERT INTO api_v2_applications VALUES(4,'423e4567-e89b-42d3-a456-426614174000');INSERT INTO api_v2_project_authorization_state VALUES(4,9,CURRENT_TIMESTAMP)");
        $this->pdo->prepare('INSERT INTO api_v2_project_external_bindings VALUES(4,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)')->execute(['other-secret-external-id',$boundElsewhere['public_id'],(int)$boundElsewhere['revision'],ProjectRevisionService::projectionHash($boundElsewhere)]);
        $beforeBindings=$this->pdo->query('SELECT * FROM api_v2_project_external_bindings ORDER BY application_pk,external_id')->fetchAll(PDO::FETCH_ASSOC);$beforePortal=$this->portalState();
        $page=api_v2_project_adoption_candidates_read($this->pdo,null,1,7,$this->headers,'page-one');self::assertSame(200,$page['status']);self::assertSame('0',$page['payload']['authorizationGeneration']);self::assertSame(str_repeat('1',32),$page['payload']['nextCursor']);
        self::assertSame([['publicId'=>str_repeat('1',32),'revision'=>'1','projectionSha256'=>ProjectRevisionService::projectionHash($first),'name'=>'First private candidate','status'=>'not_started','archived'=>false,'organizationPublicId'=>str_repeat('a',32),'clientPublicId'=>str_repeat('b',32)]],$page['payload']['projects']);
        $secondPage=api_v2_project_adoption_candidates_read($this->pdo,$page['payload']['nextCursor'],2,7,$this->headers,'page-two');self::assertSame([str_repeat('2',32),str_repeat('4',32)],array_column($secondPage['payload']['projects'],'publicId'));self::assertSame(str_repeat('4',32),$secondPage['payload']['nextCursor']);$encoded=json_encode($secondPage['payload'],JSON_THROW_ON_ERROR);self::assertStringNotContainsString('other-secret-external-id',$encoded);self::assertStringNotContainsString(str_repeat('3',32),$encoded);self::assertStringNotContainsString(str_repeat('5',32),$encoded);
        self::assertSame(['status'=>409],api_v2_project_adoption_candidates_read($this->pdo,str_repeat('4',32),200,7,$this->headers,'invalid-canonical'));$wrong=$this->headers;$wrong['epoch']='523e4567-e89b-42d3-a456-426614174000';self::assertSame(['status'=>409],api_v2_project_adoption_candidates_read($this->pdo,null,10,7,$wrong,'stale-identity'));
        foreach([[null,0],[null,201],['not-a-public-id',1]]as[$cursor,$limit]){try{api_v2_project_adoption_candidates_read($this->pdo,$cursor,$limit,7,$this->headers,'invalid');self::fail('Invalid candidate pagination must fail.');}catch(InvalidArgumentException){self::assertTrue(true);}}
        self::assertSame($beforeBindings,$this->pdo->query('SELECT * FROM api_v2_project_external_bindings ORDER BY application_pk,external_id')->fetchAll(PDO::FETCH_ASSOC));$this->assertPortalUnchanged($beforePortal);
    }
