    public function testBindingRecoveryRejectsHashOnlyDriftAndBindingAheadOfLiveHistory():void
    {
        $this->pdo->exec("INSERT INTO projects(public_id,organization_id,name,status,portal_publish_enabled,public_project_enabled,revision,source_version,invoice_billing_period,project_invoice_auto_email) VALUES('eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee',10,'Bound project','not_started',0,0,1,'browser-v1','per_invoice',0)");$id=(int)$this->pdo->lastInsertId();$this->pdo->beginTransaction();$project=(new ProjectRevisionService($this->pdo))->initialize($id,'baseline');$this->pdo->commit();
