        $this->pdo->exec("UPDATE api_v2_project_external_bindings SET project_projection_sha256='".str_repeat('f',64)."' WHERE external_id='unsafe'");
        self::assertSame(['status'=>409],api_v2_project_binding_status_read($this->pdo,'unsafe',7,$this->headers,'equal-hash-drift'));self::assertSame(['status'=>409],api_v2_project_inventory_read($this->pdo,null,10,7,$this->headers,'equal-hash-inventory'));
        $this->pdo->beginTransaction();$this->pdo->exec("UPDATE projects SET name='New live revision' WHERE id=$id");(new ProjectRevisionService($this->pdo))->advance($id,'update');$this->pdo->commit();$this->pdo->exec("UPDATE api_v2_project_external_bindings SET project_revision=1,project_projection_sha256='".str_repeat('f',64)."' WHERE external_id='unsafe'");
        self::assertSame(['status'=>409],api_v2_project_binding_status_read($this->pdo,'unsafe',7,$this->headers,'old-revision-wrong-hash'));self::assertSame(['status'=>409],api_v2_project_inventory_read($this->pdo,null,10,7,$this->headers,'old-revision-wrong-hash-inventory'));
        $this->pdo->exec("UPDATE api_v2_project_external_bindings SET project_revision=3,project_projection_sha256='$originalHash' WHERE external_id='unsafe'");
        self::assertSame(['status'=>409],api_v2_project_binding_status_read($this->pdo,'unsafe',7,$this->headers,'binding-ahead'));self::assertSame(['status'=>409],api_v2_project_inventory_read($this->pdo,null,10,7,$this->headers,'ahead-inventory'));
    }
